func maxArea(height []int) int {
	i, j, res := 0, len(height)-1, 0
	for i < j {
		if height[i] < height[j] {
			if height[i]*(j-i) > res {
				res = height[i] * (j - i)
			}
			i++
		} else {
			if height[j]*(j-i) > res {
				res = height[j] * (j - i)
			}
			j--
		}
	}
	return res
}

